/** Demo configuration: the NW_* env vars over the library's NEO4J_* set. */
export interface NorthwindConfig {
	port: number;
	database: string | undefined;
	/** Seed the classic dataset when the graph is empty (default true) */
	autoSeed: boolean;
	/** Extra synthetic orders generated by the factories (0 = seed real data only) */
	syntheticOrders: number;
	/** Connectivity for the boot check — NEO4J_* env, verified with waitUntilReachable */
	connectivity: {
		uri: string;
		database: string | undefined;
	};
}

export function loadConfig(): NorthwindConfig {
	const port = Number(process.env["NW_PORT"] ?? 3000);
	const host = process.env["NEO4J_HOST"] ?? "localhost";
	const port7474 = process.env["NEO4J_PORT"] ?? "7687";
	const protocol = process.env["NEO4J_PROTOCOL"] ?? "bolt";

	return {
		port: Number.isFinite(port) ? port : 3000,
		database: process.env["NEO4J_DATABASE"],
		autoSeed: process.env["NW_AUTOSEED"] !== "false",
		syntheticOrders: Number(process.env["NW_SYNTHETIC_ORDERS"] ?? 0),
		connectivity: {
			uri: process.env["NEO4J_URI"] ?? `${protocol}://${host}:${port7474}`,
			database: process.env["NEO4J_DATABASE"],
		},
	};
}
